              concept: '溶液是**均一**、**稳定**的**混合物**。由**溶质**（被溶解的物质）和**溶剂**（溶解溶质的物质，通常是水）组成。主要特征是：①**均一性**（各部分浓度、性质完全相同）；②**稳定性**（水分不蒸发、温度不变时，溶质不会分离析出）。溶解过程常伴随**热量变化**：如**氢氧化钠(NaOH)**放热使温度升高，**硝酸铵(NH₄NO₃)**吸热使温度降低，**氯化钠(NaCl)**温度基本不变。乳化作用则是洗洁精将油污分散成无数细小的液滴形成**乳浊液**。',
